await figma.loadFontAsync({family:"Inter",style:"Regular"});
await figma.loadFontAsync({family:"Inter",style:"Bold"});
const sec=figma.createSection();sec.name="Fernhouse - Start a return";
const OX=80,OY=200;
const C={step:{r:0.91,g:0.95,b:1},dec:{r:1,g:0.96,b:0.85},end:{r:0.86,g:0.97,b:0.88},stop:{r:1,g:0.9,b:0.9},prop:{r:0.96,g:0.96,b:0.96}};
const nodes={};
function mk(id,label,x,y,kind,shape,w=200,h=96,dashed=false){
 const s=figma.createShapeWithText();s.shapeType=shape;s.resize(w,h);
 s.x=OX+x;s.y=OY+y;s.fills=[{type:"SOLID",color:C[kind]}];
 s.text.characters=label;s.text.fontSize=16;
 s.strokes=[{type:"SOLID",color:{r:0.2,g:0.2,b:0.25}}];s.strokeWeight=id==="G"?4:1.5;
 if(dashed)s.dashPattern=[8,6];
 s.name=label.split("\n")[0];sec.appendChild(s);nodes[id]=s;return s;}
mk("A","Order list",0,120,"step","ROUNDED_RECTANGLE");
mk("B","Order detail",280,120,"step","ROUNDED_RECTANGLE");
mk("C","Delivered within\n30 days?",560,96,"dec","DIAMOND",216,144);
mk("D","Tap Start a return",880,0,"step","ROUNDED_RECTANGLE");
mk("X","Contact support\n(Start a return replaced, assumed)",880,280,"stop","ROUNDED_RECTANGLE",240,96);
mk("E","Return reasons\n(one reason, assumed)",1160,0,"step","ROUNDED_RECTANGLE",216,96);
mk("F","Drop-off point or\ncourier pickup?",1440,-24,"dec","DIAMOND",216,144);
mk("G","Confirmation\nwith QR code",1760,0,"end","ROUNDED_RECTANGLE",216,96);
mk("P","Free courier pickup\nfor orders over €100\nPROPOSED, under review",1440,240,"prop","ROUNDED_RECTANGLE",232,112,true);
function link(a,b,label,dashed=false,from="RIGHT",to="LEFT"){
 const c=figma.createConnector();
 c.connectorStart={endpointNodeId:nodes[a].id,magnet:from};
 c.connectorEnd={endpointNodeId:nodes[b].id,magnet:to};
 c.connectorEndStrokeCap="ARROW_LINES";c.strokeWeight=2;
 c.strokes=[{type:"SOLID",color:{r:0.2,g:0.2,b:0.25}}];
 if(dashed)c.dashPattern=[8,6];
 if(label){c.text.characters=label;c.text.fontSize=14;}
 sec.appendChild(c);}
link("A","B");link("B","C");
link("C","D","Yes","",  "TOP","LEFT");
link("C","X","No (after 30 days)",false,"BOTTOM","LEFT");
link("D","E");link("E","F");
link("F","G","Drop-off point");
link("F","G","Courier pickup",false,"TOP","TOP");
link("F","P","Proposed: order over €100",true,"BOTTOM","TOP");
link("P","G","",true,"RIGHT","BOTTOM");
function txt(s,x,y,size,bold){const t=figma.createText();t.fontName={family:"Inter",style:bold?"Bold":"Regular"};t.characters=s;t.fontSize=size;t.x=OX+x;t.y=OY+y;sec.appendChild(t);return t;}
txt("Fernhouse: how a customer starts a return in the app",0,-160,32,true);
txt("User flow from the order list to a return QR code. Returns are open for 30 days after delivery",0,-112,18,false);
txt("Key:  blue = screen or step   yellow = decision   green = goal (thick outline)   red = dead end   grey dashed = proposed, not current behavior   'assumed' = no source confirms it",0,460,14,false);
txt("Source: requester's description of the app and the returns doc (doc and app screens not supplied)",0,492,14,false);
sec.x=0;sec.y=0;sec.resizeWithoutConstraints(2120,780);
for(const n of sec.children){n.x+=0;}
return {section:sec.id,count:sec.children.length};

